/** String intrinsics whose observable mutable prototype surface is shared by
 * typed and dynamic receivers. Keep call selection on this one method set;
 * the runtime descriptor collection owns the corresponding implementations. */
const ORDINARY_STRING_PROTOTYPE_METHODS = new Set([
    "at",
    "charAt",
    "charCodeAt",
    "codePointAt",
    "concat",
    "endsWith",
    "includes",
    "indexOf",
    "lastIndexOf",
    "match",
    "matchAll",
    "search",
    "padEnd",
    "padStart",
    "replace",
    "replaceAll",
    "repeat",
    "slice",
    "split",
    "substr",
    "substring",
    "startsWith",
    "toLowerCase",
    "toUpperCase",
    "toLocaleLowerCase",
    "toLocaleUpperCase",
    "localeCompare",
    "normalize",
    "isWellFormed",
    "toWellFormed",
    "toString",
    "toLocaleString",
    "valueOf",
    "trim",
    "trimEnd",
    "trimLeft",
    "trimRight",
    "trimStart",
]);

const ORDINARY_VALUE_PROTOTYPE_METHODS = new Set([
    ...ORDINARY_STRING_PROTOTYPE_METHODS,
    "call", "apply", "bind",
    "toFixed", "toExponential", "toPrecision",
    "keys", "values", "entries", "forEach", "reduce", "reduceRight",
]);

const ORDINARY_OBJECT_PROTOTYPE_METHODS = new Set([
    "hasOwnProperty", "propertyIsEnumerable", "isPrototypeOf", "__defineGetter__", "__defineSetter__",
    "__lookupGetter__", "__lookupSetter__",
]);

