        const fsNamed = [
            "readFileSync",
            "writeFileSync",
            "appendFileSync",
            "existsSync",
            "accessSync",
            "readdirSync",
            "opendirSync",
            "statSync",
            "lstatSync",
            "statfsSync",
            "realpathSync",
            "readlinkSync",
            "symlinkSync",
            "linkSync",
            "mkdtempSync",
            "truncateSync",
            "utimesSync",
            "lutimesSync",
            "chownSync",
            "lchownSync",
            "chmodSync",
            "mkdirSync",
            "unlinkSync",
            "rmSync",
            "rmdirSync",
            "cpSync",
            "copyFileSync",
            "renameSync",
            "openSync",
            "closeSync",
            "fsyncSync",
            "fdatasyncSync",
            "ftruncateSync",
            "fstatSync",
            "fchmodSync",
            "fchownSync",
            "futimesSync",
            "readSync",
            "writeSync",
            "readvSync",
            "writevSync",
        ].find((exported) => this.isNamedImportFrom(calleeId, ["fs", "node:fs"], exported));
        if (fsNamed) {
            return this.emitFsCall(call, fsNamed);
        }
        const fsPromisesNamed = [
            "readFile",
            "writeFile",
            "appendFile",
            "readdir",
            "opendir",
            "statfs",
            "fstat",
            "ftruncate",
            "fsync",
            "fdatasync",
            "fchmod",
            "fchown",
            "futimes",
            "stat",
            "lstat",
            "realpath",
            "readlink",
            "symlink",
            "link",
            "mkdtemp",
            "truncate",
            "utimes",
            "lutimes",
            "chown",
            "lchown",
            "chmod",
            "access",
            "mkdir",
            "unlink",
            "rm",
            "rmdir",
            "cp",
            "copyFile",
            "rename",
        ].find((exported) => this.isNamedImportFrom(calleeId, ["fs/promises", "node:fs/promises"], exported));
        if (fsPromisesNamed) {
            return this.emitFsPromisesCall(call, fsPromisesNamed);
        }
        const pathNamed = ["join", "resolve", "normalize", "isAbsolute", "relative", "toNamespacedPath", "basename", "dirname", "extname", "parse", "format", "matchesGlob"]
            .find((exported) => this.isNamedImportFrom(calleeId, ["path", "node:path", "path/posix", "node:path/posix"], exported));
        if (pathNamed) {
            return this.emitPathCall(call, pathNamed, false);
        }
        const pathWin32Named = ["join", "resolve", "normalize", "isAbsolute", "relative", "toNamespacedPath", "basename", "dirname", "extname", "parse", "format", "matchesGlob"]
            .find((exported) => this.isNamedImportFrom(calleeId, ["path/win32", "node:path/win32"], exported));
        if (pathWin32Named) {
            return this.emitPathCall(call, pathWin32Named, true);
        }
        const utilNamed = ["format"]
            .find((exported) => this.isNamedImportFrom(calleeId, ["util", "node:util"], exported));
        if (utilNamed) {
            return this.emitUtilCall(call, utilNamed);
        }
        const dnsNamed = ["lookup", "resolve", "resolve4", "resolve6", "reverse", "resolveCname", "resolveAny", "lookupService", "getDefaultResultOrder", "setDefaultResultOrder"]
            .find((exported) => this.isNamedImportFrom(calleeId, ["dns", "node:dns"], exported));
        if (dnsNamed) {
            return this.emitDnsCall(call, dnsNamed);
        }
        const dnsPromisesNamed = ["lookup", "resolve", "resolve4", "resolve6", "reverse", "resolveCname", "resolveAny", "lookupService", "getDefaultResultOrder", "setDefaultResultOrder"]
            .find((exported) => this.isNamedImportFrom(calleeId, ["dns/promises", "node:dns/promises"], exported));
        if (dnsPromisesNamed) {
            return this.emitDnsPromisesCall(call, dnsPromisesNamed);
        }
